SELECT id, trademark_name, trademark_no, category, sub_category, valid_date, company_name, remark, create_time, update_time FROM we_trademark
AND (trademark_name LIKE CONCAT('%', #{keyword}, '%') OR trademark_no LIKE CONCAT('%', #{keyword}, '%') OR sub_category LIKE CONCAT('%', #{keyword}, '%') OR company_name LIKE CONCAT('%', #{keyword}, '%'))
AND category = #{category}
AND company_name LIKE CONCAT('%', #{companyName}, '%')
ORDER BY id DESC
LIMIT #{offset}, #{limit}

